#if canImport(UIKit)
import UIKit

public enum KenshikiIOSColorRole {
    case background
    case groupedBackground
    case surface
    case text
    case secondary
    case separator
    case accent
    case cameraBackground
    case levelGood
    case levelWarning
    case levelTilted
}

public enum KenshikiIOSTextRole {
    case title
    case body
    case caption
    case action
}

@MainActor public enum KenshikiIOSDesign {
    public static func color(_ role: KenshikiIOSColorRole) -> UIColor {
        switch role {
        case .background: return .systemBackground
        case .groupedBackground: return .systemGroupedBackground
        case .surface: return .secondarySystemGroupedBackground
        case .text: return .label
        case .secondary: return .secondaryLabel
        case .separator: return .separator
        case .accent: return .systemBlue
        case .cameraBackground: return .black
        case .levelGood: return .systemGreen
        case .levelWarning: return .systemOrange
        case .levelTilted: return .systemRed
        }
    }
    public static func font(_ role: KenshikiIOSTextRole) -> UIFont {
        switch role {
        case .title: return .preferredFont(forTextStyle: .title1)
        case .body: return .preferredFont(forTextStyle: .body)
        case .caption: return .preferredFont(forTextStyle: .footnote)
        case .action: return .preferredFont(forTextStyle: .headline)
        }
    }
    public static func primaryConfiguration() -> UIButton.Configuration {
        var configuration = UIButton.Configuration.filled()
        configuration.baseForegroundColor = color(.background)
        configuration.baseBackgroundColor = color(.text)
        return configuration
    }
    public static func secondaryConfiguration() -> UIButton.Configuration {
        let configuration: UIButton.Configuration
        if #available(iOS 26.0, *) {
            configuration = .glass()
        } else {
            configuration = .tinted()
        }
        return configuration
    }
    public static func tertiaryConfiguration() -> UIButton.Configuration {
        let configuration = UIButton.Configuration.plain()
        return configuration
    }
}
#endif

